vec2 complexMultiply(vec2 a, vec2 b)
{
    return vec2(a.x * b.x - a.y * b.y, a.x * b.y + a.y * b.x);
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // Normalized pixel coordinates (from 0 to 1)
    vec2 uv = fragCoord/iResolution.xy;
    uv -= vec2(.5f);
    uv *= 2.0f ;
    uv.x *= iResolution.x / iResolution.y;

    vec2 current = uv;
    vec2 cmplxZ = vec2(cos(iTime * 0.5f), sin(iTime * 0.1f));

    for(int i = 0; (length(current) > 0.01f && length(current) < 1000.0f) && i < 300;  i++)
    {
        current = complexMultiply(current, current) + cmplxZ;
    }

    // Time varying pixel color
    vec4 col = texture(iChannel0, vec2(length(current) / 10000.0f, 0));

    // Output to screen
    fragColor = col;
}
